const s=/chinese|китай|қытай|кытай|汉语|中文|语文/i;function i(...t){return t.some(e=>!!e&&s.test(e))}function r(...t){const e=t.filter(Boolean).join(" ").toLowerCase(),n=s.test(e);return n&&/(tech|техн|科技)/i.test(e)?"chineseTech":n&&/(hum|гуман|文科)/i.test(e)?"chineseHum":n?"chinese":/math|матем|数学/i.test(e)?"math":/phys|физи|物理/i.test(e)?"physics":/chem|хими|化学/i.test(e)?"chemistry":"unknown"}export{i,r as s};
